       public MySubClass() { }

       // Must implement interface method
       public void MyInterfaceMethod() {
           Console.WriteLine("Subclass implementation");
       }

       // Base methods can still be overridden
       public override void MyOtherMethod() {
           Console.WriteLine("Subclass implementation");
       }
   }
   ```

