    public string Description { get; set; }
    public List<string> RequiredSkills { get; set; }
    public DateTime StartTime { get; set; }
    public DateTime EndTime { get; set; }

    public Task(string description, List<string> requiredSkills, DateTime startTime, DateTime endTime)
    {
        Description = description;
        RequiredSkills = requiredSkills;
        StartTime = startTime;
        EndTime = endTime;
    }
}

public static List<Volunteer> MatchVolunteersToTasks(List<Volunteer> volunteers, List<Task> tasks)
{
    var matchedVolunteers = new List<Volunteer>();

    foreach (var task in tasks)
    {
        foreach (var volunteer in volunteers)
        {
            if (volunteer.Skills.Intersect(task.RequiredSkills).Count() > 0 &&
                volunteer.AvailabilityFrom >= task.StartTime &&
                volunteer.AvailabilityTo <= task.EndTime)
            {
                matchedVolunteers.Add(volunteer);
                break; // Only one match per volunteer for this task
            }
        }
    }

    return matchedVolunteers;
}
```

