```typescript
// src/websocket.gateway.ts
import { WebSocketGateway, OnGatewayConnection, OnGatewayDisconnect, MessageBody, SubscribeMessage, WebSocketServer } from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from '../users/entities/user.entity';
import { ChatMessage } from './entities/chat-message.entity';

@WebSocketGateway({ cors: true })
export class WebsocketGateway implements OnGatewayConnection, OnGatewayDisconnect {
  @WebSocketServer()
  server: Server;

  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
    @InjectRepository(ChatMessage)
    private readonly chatMessageRepository: Repository<ChatMessage>,
  ) {}

  handleConnection(client: Socket) {
    console.log(`Client connected: ${client.id}`);
  }

  handleDisconnect(client: Socket) {
    console.log(`Client disconnected: ${client.id}`);
  }

  @SubscribeMessage('newMessage')
  async handleMessage(@MessageBody() data: any, client: Socket): Promise<void> {
    const user = await this.userRepository.findOne(data.userId);
    if (!user) {
      throw new Error('User not found');
    }
    const message = new ChatMessage();
    message.content = data.message;
    message.user = user;
    message.timestamp = new Date();

    await this.chatMessageRepository.save(message);

    // Broadcast the message to all clients
    this.server.emit('message', message);
  }
}
```

