Here's a method to calculate the SDF for a rectangle defined by its position, size, and rotation (optional):

```hlsl
float RectangleSDF(float2 pos, float2 size, float4x4 transform, float3 rotation) {
    // Transform the point into the rectangle's local space
    float2 localPos = mul(transform, float4(pos - 0.5 * size, 0.0, 1.0)).xy;

    // Rotate the point back to the original coordinate system if needed
    if (rotation != float3(0, 0, 0)) {
        float angle = rotation.z;
        float c = cos(angle);
        float s = sin(angle);
        float2 rotatedPos = float2(
            localPos.x * c + localPos.y * s,
            -localPos.x * s + localPos.y * c
        );
        localPos = rotatedPos;
    }

    // Calculate the SDF for the rectangle in local space
    float2 diff = abs(localPos) - size * 0.5;

    return min(max(diff.x, diff.y), 0.0) + length(max(diff, 0.0));
}

