def factorial(n):
    """
    Calculate the factorial of a given number n.

    :param n: int - the number to calculate the factorial for
    :return: int - the factorial of n
    """
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

def check_factorial():
    test_cases = [(0, 1), (1, 1), (5, 120), (10, 3628800)]
    for n, expected in test_cases:
        result = factorial(n)
        assert result == expected, f"Expected factorial({n}) to be {expected}, got {result} instead."
        print(f"PASS: factorial({n}) = {result}")

if __name__ == "__main__":
    check_factorial()
```

