	"fmt"
)

// SortStringsBy7thChar sorts an array of strings based on the 7th character.
func SortStringsBy7thChar(arr []string) []string {
	n := len(arr)
	if n == 0 {
		return arr
	}

	// Create a slice to hold the index of each string for sorting
	indexes := make([]int, n)
	for i := range indexes {
		indexes[i] = i
	}

	// Perform a stable sort by comparing the 7th characters
	sort.SliceStable(indexes, func(i, j int) bool {
		// Get the 7th character, treating strings shorter than 7 chars as if they have '\x00'
		charI := byte(arr[indexes[i]][6])
		charJ := byte(arr[indexes[j]][6])

		return charI < charJ
	})

	// Reorder the original array based on the sorted indexes
	sortedArr := make([]string, n)
	for i, index := range indexes {
		sortedArr[i] = arr[index]
	}

	return sortedArr
}

